+        // check.
+        final DetailAST typeMods = ast.findFirstToken(TokenTypes.MODIFIERS);
+        final boolean isStaticInnerType = typeMods != null && typeMods.findFirstToken(TokenTypes.LITERAL_STATIC) != null;
+        final String frameName;
